contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry point for property test
    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public payable {
        // Ensure any ETH forwarded by the test when calling initialize is zero (initialize is nonpayable),
        // but follow the template: no precondition on parameters is needed.
        require(true);

        // Read initial initialized flag (should be false for fresh deployment but we don't require it)
        bool beforeInitialized = c.initialized();

        // Try first initialize call and capture whether it reverted
        bool firstReverted;
        try c.initialize(baseToken, nft, virtualBaseTokenReserves, virtualNftReserves, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Observe initialized after first attempt
        bool afterInitialized = c.initialized();

        // Try calling initialize a second time with same parameters to check idempotent/guard behaviour
        bool secondReverted;
        try c.initialize(baseToken, nft, virtualBaseTokenReserves, virtualNftReserves, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule asserted:
        // If the first initialize succeeded (did not revert) then initialized must be true afterwards,
        // and any subsequent initialize call must revert (AlreadyInitialized).
        // If the first initialize reverted then we make no further guarantees about initialized or second call.
        assert( (firstReverted) || (!firstReverted && afterInitialized && secondReverted) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry point for property test
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        address stolenOracleCaller
    ) public payable {
        // no precondition on parameters
        require(true);

        // Read public observable virtual reserves before the operation
        uint128 vb_before = c.virtualBaseTokenReserves();
        uint128 vn_before = c.virtualNftReserves();

        // Compute weightSum via public sumWeightsAndValidateProof by calling with empty merkle (merkleRoot may be zero on fresh pool)
        C.MerkleMultiProof memory emptyProof;
        emptyProof.proof = new bytes32[](0);
        emptyProof.flags = new bool[](0);

        // We will attempt to call sell and catch whether it reverts
        bool reverted;
        uint256 netOutputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        try c.sell(tokenIds, tokenWeights, emptyProof, new IStolenNftOracle.Message[](0)) returns (uint256 noa, uint256 fa, uint256 pfa) {
            reverted = false;
            netOutputAmount = noa;
            feeAmount = fa;
            protocolFeeAmount = pfa;
        } catch {
            reverted = true;
        }

        // After attempt, read virtual reserves and price
        uint128 vb_after = c.virtualBaseTokenReserves();
        uint128 vn_after = c.virtualNftReserves();

        // If the call reverted we make no guarantees. If it succeeded then:
        // 1) The returned netOutputAmount must equal the value computed by sellQuote on the public view.
        // 2) The virtualBaseTokenReserves must have decreased by at least (netOutputAmount + feeAmount + protocolFeeAmount)
        //    (implementation subtracts that sum from virtualBaseTokenReserves on successful sell).

        (uint256 q_netOutputAmount, uint256 q_feeAmount, uint256 q_protocolFeeAmount) = c.sellQuote(c.sumWeightsAndValidateProof(tokenIds, tokenWeights, emptyProof));

        // Build the assertion: either reverted, or both the quoted amounts equal returned amounts and vb change is consistent
        assert(
            reverted || (
                q_netOutputAmount == netOutputAmount
                && q_feeAmount == feeAmount
                && q_protocolFeeAmount == protocolFeeAmount
                && vb_before >= vb_after
                && uint256(vb_before) - uint256(vb_after) >= uint256(netOutputAmount) + uint256(feeAmount) + uint256(protocolFeeAmount)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry point for property test
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights
    ) public payable {
        require(tokenIds.length == tokenWeights.length && tokenIds.length > 0);

        // empty merkle proof (works when merkleRoot == 0 or when provided leafs match)
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        proof.flags = new bool[](0);

        // observe virtualNftReserves before
        uint128 vn_before = c.virtualNftReserves();

        bool reverted;
        uint256 ret_netInputAmount;
        uint256 ret_feeAmount;
        uint256 ret_protocolFeeAmount;

        try c.buy{value: 0}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            ret_netInputAmount = n;
            ret_feeAmount = f;
            ret_protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // compute sumWeights via public helper (will revert if proof invalid)
        uint256 sumWeights = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof);

        // compute quoted amounts
        (uint256 q_netInputAmount, , ) = c.buyQuote(sumWeights);

        // observe virtualNftReserves after
        uint128 vn_after = c.virtualNftReserves();

        // Assert: if the buy call succeeded then (1) returned netInputAmount equals buyQuote, and (2) virtualNftReserves decreased by exactly sumWeights
        assert(reverted || (q_netInputAmount == ret_netInputAmount && uint256(vn_before) == uint256(vn_after) + sumWeights));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry point
    function run(
        uint256[] calldata inputTokenIds,
        uint256[] calldata inputTokenWeights,
        uint256[] calldata outputTokenIds,
        uint256[] calldata outputTokenWeights
    ) public payable {
        // require non-empty and equal lengths for each side, and input weight sum >= output weight sum to avoid obvious revert
        require(inputTokenIds.length == inputTokenWeights.length && outputTokenIds.length == outputTokenWeights.length);
        require(inputTokenIds.length > 0 && outputTokenIds.length > 0);

        // empty Merkle proofs (valid when merkleRoot == 0)
        C.MerkleMultiProof memory emptyProof;
        emptyProof.proof = new bytes32[](0);
        emptyProof.flags = new bool[](0);

        // compute input and output weight sums via public view helper; this may revert for bad proofs
        uint256 inputWeightSum = c.sumWeightsAndValidateProof(inputTokenIds, inputTokenWeights, emptyProof);
        uint256 outputWeightSum = c.sumWeightsAndValidateProof(outputTokenIds, outputTokenWeights, emptyProof);

        // precondition for change to succeed: inputWeightSum >= outputWeightSum
        require(inputWeightSum >= outputWeightSum);

        // call change and catch revert
        bool reverted;
        uint256 ret_feeAmount;
        uint256 ret_protocolFeeAmount;
        try c.change{value: 0}(inputTokenIds, inputTokenWeights, emptyProof, new C.IStolenNftOracle.Message[](0), outputTokenIds, outputTokenWeights, emptyProof) returns (uint256 feeAmount, uint256 protocolFee) {
            reverted = false;
            ret_feeAmount = feeAmount;
            ret_protocolFeeAmount = protocolFee;
        } catch {
            reverted = true;
        }

        // compute quoted values from changeFeeQuote
        (uint256 q_feeAmount, uint256 q_protocolFeeAmount) = c.changeFeeQuote(inputWeightSum);

        // Assert: if change did not revert then the returned amounts match the quote
        assert(reverted || (ret_feeAmount == q_feeAmount && ret_protocolFeeAmount == q_protocolFeeAmount));
    }

    receive() external payable {}
}
